# 方法一：單調棧（最優解）
class Solution:
    def maximalRectangle(self, matrix: List[List[str]]) -> int:
        if not matrix or not matrix[0]:
            return 0

        n = len(matrix[0])
        heights = [0] * n
        max_area = 0

        for row in matrix:
            # 更新高度陣列
            for j in range(n):
                if row[j] == '1':
                    heights[j] += 1
                else:
                    heights[j] = 0

            # 對當前高度陣列求最大矩形
            max_area = max(max_area, self.largestRectangleArea(heights))

        return max_area

    def largestRectangleArea(self, heights: List[int]) -> int:
        """使用單調棧求柱狀圖最大矩形"""
        stack = []
        max_area = 0
        heights = [0] + heights + [0]  # 添加哨兵

        for i in range(len(heights)):
            while stack and heights[i] < heights[stack[-1]]:
                h = heights[stack.pop()]
                w = i - stack[-1] - 1
                max_area = max(max_area, h * w)
            stack.append(i)

        return max_area


# 方法二：動態規劃
class Solution:
    def maximalRectangle(self, matrix: List[List[str]]) -> int:
        if not matrix or not matrix[0]:
            return 0

        m, n = len(matrix), len(matrix[0])

        # 維護三個 DP 陣列
        heights = [0] * n  # 當前位置的高度
        left = [0] * n     # 左邊界（含）
        right = [n] * n    # 右邊界（不含）

        max_area = 0

        for i in range(m):
            # 更新高度
            for j in range(n):
                if matrix[i][j] == '1':
                    heights[j] += 1
                else:
                    heights[j] = 0

            # 更新左邊界
            cur_left = 0
            for j in range(n):
                if matrix[i][j] == '1':
                    left[j] = max(left[j], cur_left)
                else:
                    left[j] = 0
                    cur_left = j + 1

            # 更新右邊界
            cur_right = n
            for j in range(n - 1, -1, -1):
                if matrix[i][j] == '1':
                    right[j] = min(right[j], cur_right)
                else:
                    right[j] = n
                    cur_right = j

            # 計算面積
            for j in range(n):
                max_area = max(max_area, heights[j] * (right[j] - left[j]))

        return max_area


# 方法三：簡潔版單調棧
class Solution:
    def maximalRectangle(self, matrix: List[List[str]]) -> int:
        if not matrix:
            return 0

        max_area = 0
        heights = [0] * len(matrix[0])

        for row in matrix:
            # 更新高度
            for i, val in enumerate(row):
                heights[i] = heights[i] + 1 if val == '1' else 0

            # 計算最大矩形（使用單調棧）
            stack = [-1]
            for i in range(len(heights)):
                while stack[-1] != -1 and heights[i] < heights[stack[-1]]:
                    h = heights[stack.pop()]
                    w = i - stack[-1] - 1
                    max_area = max(max_area, h * w)
                stack.append(i)

            # 處理剩餘元素
            while stack[-1] != -1:
                h = heights[stack.pop()]
                w = len(heights) - stack[-1] - 1
                max_area = max(max_area, h * w)

        return max_area

