// 逐列累積高度，每一列都當作直方圖求最大矩形（單調堆疊）
// 時間複雜度: O(m·n)，空間複雜度: O(n)
int maximalRectangle(char** matrix, int matrixSize, int* matrixColSize) {
    int n = matrixColSize[0];
    int* heights = calloc(n, sizeof(int));
    int* stack = malloc(sizeof(int) * (n + 1));
    int best = 0;

    for (int i = 0; i < matrixSize; i++) {
        for (int j = 0; j < n; j++) {
            heights[j] = matrix[i][j] == '1' ? heights[j] + 1 : 0;
        }
        int top = 0;
        for (int j = 0; j <= n; j++) {
            int h = (j == n) ? 0 : heights[j];
            while (top > 0 && heights[stack[top - 1]] > h) {
                int height = heights[stack[--top]];
                int left = top > 0 ? stack[top - 1] : -1;
                if (height * (j - left - 1) > best) best = height * (j - left - 1);
            }
            stack[top++] = j;
        }
    }
    free(heights);
    free(stack);
    return best;
}

